-- 127: Original BrillaPrep WASSCE Islamic Religious Studies syllabus evidence beta questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_031', 'topic_was_irs_7', 'subj_wassce_irs', 'exam_wassce', 'What title is commonly given to Abu Bakr as the first caliph?', 'multiple_choice', '["A. Al-Faruq","B. Dhu al-Nurayn","C. Al-Siddiq","D. Saifullah"]', 'C', 'Abu Bakr was known as al-Siddiq, reflecting his truthfulness and steadfast affirmation of the Prophet. Therefore the correct answer is C: Al-Siddiq.', 'easy', 1, 1, 90, 'st_was_irs_7', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_032', 'topic_was_irs_7', 'subj_wassce_irs', 'exam_wassce', 'Which caliph is especially associated with organising provinces and public administration as the state expanded?', 'multiple_choice', '["A. Abu Lahab","B. Abu Jahl","C. Walid ibn al-Mughira","D. Umar ibn al-Khattab"]', 'D', 'Umar developed administrative, judicial and welfare arrangements and was known for accountability as Muslim territories expanded. Therefore the correct answer is D: Umar ibn al-Khattab.', 'medium', 2, 2, 90, 'st_was_irs_7', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_033', 'topic_was_irs_7', 'subj_wassce_irs', 'exam_wassce', 'Why is Uthman ibn Affan called Dhu al-Nurayn?', 'multiple_choice', '["A. He married two daughters of Prophet Muhammad in succession","B. He led two migrations in the same day","C. He compiled two different Qur’ans","D. He built two Ka’bahs"]', 'A', 'The title means possessor of the two lights and refers to his marriages to Ruqayyah and, after her death, Umm Kulthum. Therefore the correct answer is A: He married two daughters of Prophet Muhammad in succession.', 'hard', 1, 1, 90, 'st_was_irs_7', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_034', 'topic_was_irs_7', 'subj_wassce_irs', 'exam_wassce', 'Which contribution is strongly associated with Ali ibn Abi Talib?', 'multiple_choice', '["A. Opposition to the first revelation","B. Knowledge, courage and close service to the Prophet","C. Rule as a Byzantine emperor","D. Prohibition of learning"]', 'B', 'Ali was among the earliest Muslims, was raised close to the Prophet and became known for learning, judgment and courage. Therefore the correct answer is B: Knowledge, courage and close service to the Prophet.', 'easy', 2, 2, 90, 'st_was_irs_7', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_035', 'topic_was_irs_7', 'subj_wassce_irs', 'exam_wassce', 'Why did Muslim scholars develop detailed narrator criticism?', 'multiple_choice', '["A. To prevent any Hadith from being studied","B. To judge people only by their wealth","C. To distinguish reliable reports from weak or fabricated ones","D. To replace the Qur’an with genealogy"]', 'C', 'Biographical and transmission analysis protected religious knowledge by checking memory, integrity, chronology and opportunities for narrators to meet. Therefore the correct answer is C: To distinguish reliable reports from weak or fabricated ones.', 'medium', 3, 3, 90, 'st_was_irs_7', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_036', 'topic_was_irs_8', 'subj_wassce_irs', 'exam_wassce', 'What does amanah require in business dealings?', 'multiple_choice', '["A. Concealing defects from buyers","B. Changing agreed measures secretly","C. Breaking promises whenever profit increases","D. Trustworthiness and faithful discharge of responsibility"]', 'D', 'Amanah requires honesty with property, information and obligations, making it central to trustworthy trade and public responsibility. Therefore the correct answer is D: Trustworthiness and faithful discharge of responsibility.', 'hard', 2, 2, 90, 'st_was_irs_8', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_037', 'topic_was_irs_8', 'subj_wassce_irs', 'exam_wassce', 'What social purpose does Zakah serve?', 'multiple_choice', '["A. Purifying qualifying wealth and supporting eligible people and causes","B. Increasing inequality as an objective","C. Replacing every voluntary good deed","D. Funding only luxury consumption"]', 'A', 'Zakah combines worship with structured social support and reminds owners that wealth carries duties toward the wider community. Therefore the correct answer is A: Purifying qualifying wealth and supporting eligible people and causes.', 'easy', 1, 1, 90, 'st_was_irs_8', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_038', 'topic_was_irs_8', 'subj_wassce_irs', 'exam_wassce', 'Which conduct best reflects adl?', 'multiple_choice', '["A. Favouring relatives regardless of evidence","B. Acting justly even when personal interest points elsewhere","C. Using different measures for buyers and sellers","D. Withholding every worker’s agreed wage"]', 'B', 'Adl means justice and fairness. Islamic ethics require consistent standards and protection of rights rather than biased advantage. Therefore the correct answer is B: Acting justly even when personal interest points elsewhere.', 'medium', 2, 2, 90, 'st_was_irs_8', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_039', 'topic_was_irs_8', 'subj_wassce_irs', 'exam_wassce', 'How should disagreement be handled according to Islamic ethics?', 'multiple_choice', '["A. With insults and deliberate falsehood","B. By assuming every opponent is dishonest","C. With evidence, respectful speech and a sincere search for reconciliation","D. By spreading unverified accusations"]', 'C', 'Truthfulness, restraint and peacemaking protect dignity and make resolution more likely even when the parties continue to disagree. Therefore the correct answer is C: With evidence, respectful speech and a sincere search for reconciliation.', 'hard', 1, 1, 90, 'st_was_irs_8', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_040', 'topic_was_irs_8', 'subj_wassce_irs', 'exam_wassce', 'What does stewardship of the earth imply?', 'multiple_choice', '["A. Natural resources have no moral value","B. Waste is acceptable when ownership is private","C. Future generations have no interests","D. People should use resources responsibly and avoid waste and harm"]', 'D', 'The idea of khalifah frames human power as accountable stewardship, encouraging beneficial use, moderation and protection from corruption or needless damage. Therefore the correct answer is D: People should use resources responsibly and avoid waste and harm.', 'easy', 3, 3, 90, 'st_was_irs_8', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.', 'https://www.waeconline.org.ng/e-learning/Islamic/IRKmain.html', 0, 1 FROM questions WHERE id BETWEEN 'q_was_irs_b001_031' AND 'q_was_irs_b001_040';
